cd /home/ubuntu/.agent-ml-research-idea_gen_0509_16/projects/exec-sim-repair-verifier/docs/paper && python3 -c "
import re
tex_cites = set()
for f in ['abstract.tex','introduction.tex','method.tex','experiments.tex','related_work.tex','conclusion.tex','checklist.tex','appendix.tex']:
    with open(f) as fh:
        for m in re.finditer(r'\\\\cite[tp]?\{([^}]+)\}', fh.read()):
            for k in m.group(1).split(','):
                tex_cites.add(k.strip())
with open('references.bib') as fh:
    bib_keys = set(re.findall(r'@\w+\{(\w+)', fh.read()))
orphan_cites = tex_cites - bib_keys
orphan_bibs = bib_keys - tex_cites
print(f'Cite keys in tex: {len(tex_cites)}')
print(f'Bib keys: {len(bib_keys)}')
if orphan_cites: print(f'MISSING from bib: {orphan_cites}')
else: print('All citations found in bib')
if orphan_bibs: print(f'Unused bib entries: {len(orphan_bibs)}')
"
